      "condition_item_1": "অ্যাকাউন্ট রেজিস্ট্রেশন সময় ≥1 দিন এবং",
      "condition_item_2": "সমগ্র পাঠানো মেসেজ সংখ্যা ≥5 টি",
      "reward_content":
          "🎯 পুরস্কারের বিষয়বস্তু:\n\n✅ শর্ত পূরণ করলে ধনুক খুলুন এবং পয়েন্ট নিন!\n\n✅ একাধিক অধীনস্তদের শর্ত পূরণ করলে একাধিকবার খুলতে পারবেন, পুরস্কারের কোনো সীমা নেই!\n\n💡 কিভাবে কাজ করবেন?\n\nবন্ধুদের নিবন্ধন করতে এবং কাজের মধ্যে বার্তা পাঠাতে আমন্ত্রণ জানান\n\nকার্যক্রম পৃষ্ঠায় “ধনুক খুলুন” ক্লিক করুন এবং স্বয়ংক্রিয়ভাবে যোগ্যতা যাচাই করুন\n\nপয়েন্টগুলি রিয়েল-টাইমে জমা হবে এবং দুর্দান্ত উপহারগুলির জন্য বিনিময় করা যাবে!\n\n❗️ নোট:\n\nসিস্টেম স্বয়ংক্রিয়ভাবে অধীনস্তদের কার্যকর কাজগুলি শনাক্ত করে।\n\nপয়েন্ট বিতরণে ১০ মিনিটের দেরি হতে পারে\n\nকার্যক্রম দীর্ঘ সময়ের জন্য বৈধ, ধারাবাহিক প্রচারকে উৎসাহিত করে",
      "reward_tip": "শর্ত পূরণ করলে বক্সটি খুলে পয়েন্ট গ্রহণ করুন！",
      "how_to_participate": "কিভাবে অংশগ্রহণ করবেন？",
      "participate_step_1":
          "বন্ধুকে রেজিস্টার করানো এবং টাস্কে অংশগ্রহণ করে মেসেজ পাঠানো, তারপর এক্টিভিটি পেজের \"বক্স খুলুন\" বাটনে ক্লিক করুন",
      "participate_step_2":
          "সিস্টেম স্বয়ংক্রিয়ভাবে যাচাই করবে, পয়েন্ট রিয়েল-টাইমে ক্রেডিট করা হবে, প্রথমে আসা প্রথমে পায়！",
      "invitation_step_1":
          "1. \"কপি\" বাটনে ক্লিক করুন, রেফারেল লিঙ্ক বা শেয়ার পদ্ধতি কপি করুন",
      "invitation_step_2":
          "2. কপি করা লিঙ্ক পাঠানো, বন্ধুদের আপনার লিঙ্ক শেয়ার করানো",
      "invitation_step_3":
          "3. আপনার বন্ধু টাস্ক সম্পন্ন করলে অতিরিক্ত পুরস্কার পাওয়া যাবে",
      "current_reach_level2_reward_points":
          "এখনই %s জন সাবর্ডিনেট সেকেন্ড লেভেল ব্যবহারকারীতে আপগ্রেড হয়েছে, আপনি %s পয়েন্ট পুরস্কার পেতে পারেন",
      "invite_subordinates_reach_level2_reward":
          "সরাসরি সাবর্ডিনেটকে সেকেন্ড লেভেল ব্যবহারকারীতে আপগ্রেড করানো হলে পয়েন্ট পুরস্কার পাওয়া যাবে",
      "system_notice": "সিস্টেম নোটিশ：",
      "notice_content":
          "সিস্টেম স্বয়ংক্রিয়ভাবে সাবর্ডিনেটের বৈধ টাস্ক সনাক্ত করে, পয়েন্ট প্রদানে 10 মিনিটের বিলম্ব থাকতে পারে",
      "activity_period":
          "এক্টিভিটি দীর্ঘকালীনভাবে কার্যকর, ক্রমাগত প্রোমোশনের জন্য উত্সাহিত করা হয়",
